class Solution {
    public int kthPairGap(int[] heights, int k) {
        int n = heights.length, t = 0;
        int[] gaps = new int[n * (n - 1) / 2];
        for (int i = 0; i < n; i++) for (int j = i + 1; j < n; j++) gaps[t++] = Math.abs(heights[i] - heights[j]);
        Arrays.sort(gaps);
        return gaps[k - 1];
    }
}

