int kthPairGap(int* heights, int heightsSize, int k) {
    int n = heightsSize, t = 0;
    int* gaps = malloc((size_t) n * (n - 1) / 2 * sizeof(int) + 1);
    for (int i = 0; i < n; i++) for (int j = i + 1; j < n; j++) gaps[t++] = abs(heights[i] - heights[j]);
    qsort(gaps, t, sizeof(int), cmpInt);
