class Solution:
    def kthPairGap(self, heights: List[int], k: int) -> int:
        s = sorted(heights)
        n = len(s)
        def pairs_within(d):
            total = left = 0
            for right in range(n):
                while s[right] - s[left] > d:
                    left += 1
                total += right - left
            return total
        lo, hi = 0, s[-1] - s[0]
        while lo < hi:
            mid = (lo + hi) // 2
            if pairs_within(mid) >= k:
                hi = mid
            else:
                lo = mid + 1
        return lo

