class Solution {
    public int kthPairGap(int[] heights, int k) {
        int[] s = heights.clone();
        Arrays.sort(s);
        int lo = 0, hi = s[s.length - 1] - s[0];
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (pairsWithin(s, mid) >= k) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }

    private long pairsWithin(int[] s, int d) {
        long total = 0;
        for (int right = 0, left = 0; right < s.length; right++) {
            while (s[right] - s[left] > d) left++;
            total += right - left;
        }
        return total;
    }
}

