static int cmpInt(const void* a, const void* b) {
    int p = *(const int*) a, q = *(const int*) b;
    return (p > q) - (p < q);
}

static long long pairsWithin(const int* s, int n, int d) {
    long long total = 0;
    for (int right = 0, left = 0; right < n; right++) {
        while (s[right] - s[left] > d) left++;
        total += right - left;
    }
    return total;
}

int kthPairGap(int* heights, int heightsSize, int k) {
    int n = heightsSize;
    int* s = malloc(n * sizeof(int));
    memcpy(s, heights, n * sizeof(int));
    qsort(s, n, sizeof(int), cmpInt);
    int lo = 0, hi = s[n - 1] - s[0];
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (pairsWithin(s, n, mid) >= k) hi = mid;
        else lo = mid + 1;
    }
    free(s);
    return lo;
}
